function validate([bottomLeft, topRight]) {
  if (!Array.isArray(bottomLeft) || !Array.isArray(topRight) || bottomLeft.length !== topRight.length) return 'bottomLeft and topRight need the same length.';
  if (bottomLeft.length < 2 || bottomLeft.length > 1000) return 'There are 2 to 1000 rectangles.';
  for (let i = 0; i < bottomLeft.length; i++) {
    const corners = [bottomLeft[i], topRight[i]];
    if (corners.some(p => !Array.isArray(p) || p.length !== 2)) return 'Each corner is a pair [x, y].';
    if (corners.flat().some(v => !Number.isInteger(v) || v < 1 || v > 10000000)) return 'Coordinates are integers from 1 to 10^7.';
    if (bottomLeft[i][0] >= topRight[i][0] || bottomLeft[i][1] >= topRight[i][1]) return 'Each bottom-left corner must be strictly below and left of its top-right corner.';
  }
  return null;
}

