function largestSquareArea(bottomLeft, topRight) {
  // Small coordinates only: try every integer side and position, largest side first,
  // and count how many rectangles contain that square.
  const limit = Math.max(...topRight.flat());
  for (let s = limit; s >= 1; s--) {
    for (let x = 1; x + s <= limit; x++) {
      for (let y = 1; y + s <= limit; y++) {
        let holders = 0;
        for (let i = 0; i < bottomLeft.length; i++) {
          const [a, b] = bottomLeft[i], [c, d] = topRight[i];
          if (a <= x && x + s <= c && b <= y && y + s <= d) holders++;
        }
        if (holders >= 2) return s * s;
      }
    }
  }
  return 0;
}

