function generate(rand, size) {
  const n = size === 'large' ? 1000 : 2 + Math.floor(rand() * 5);
  const limit = size === 'large' ? 10000000 : 4 + Math.floor(rand() * 9);
  // Rectangle sides range from tiny to most of the plane, so overlaps vary from none to large.
  const maxSide = Math.max(1, Math.floor(limit * (0.05 + rand() * 0.6)));
  const bottomLeft = [], topRight = [];
  for (let i = 0; i < n; i++) {
    const width = 1 + Math.floor(rand() * Math.min(maxSide, limit - 1));
    const height = 1 + Math.floor(rand() * Math.min(maxSide, limit - 1));
    const a = 1 + Math.floor(rand() * (limit - width));
    const b = 1 + Math.floor(rand() * (limit - height));
    bottomLeft.push([a, b]);
    topRight.push([a + width, b + height]);
  }
  return [bottomLeft, topRight];
}
